  "branch.merge": "\u0421\u043B\u0438\u0442\u044C {branch} \u0441 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0432\u0435\u0442\u043A\u043E\u0439\u2026",
  "branch.rebase": "\u041F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0432\u0435\u0442\u043A\u0443 \u043D\u0430 {branch}\u2026",
