  "branch.renameTitle": "\u041F\u0435\u0440\u0435\u0438\u043C\u0435\u043D\u043E\u0432\u0430\u0442\u044C \u0432\u0435\u0442\u043A\u0443",
  "branch.renameText": "\u041D\u043E\u0432\u043E\u0435 \u0438\u043C\u044F \u0434\u043B\u044F {branch}.",
  "branch.newName": "\u0418\u043C\u044F \u0432\u0435\u0442\u043A\u0438",
  "branch.renameAction": "\u041F\u0435\u0440\u0435\u0438\u043C\u0435\u043D\u043E\u0432\u0430\u0442\u044C",
  "branch.deleteTitle": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0432\u0435\u0442\u043A\u0443",
  "branch.deleteText": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C {branch}? \u0418\u043C\u044F \u0432\u0435\u0442\u043A\u0438 \u0431\u0443\u0434\u0435\u0442 \u0443\u0434\u0430\u043B\u0435\u043D\u043E; \u0435\u0451 \u043A\u043E\u043C\u043C\u0438\u0442\u044B \u043E\u0441\u0442\u0430\u043D\u0443\u0442\u0441\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0438\u0437 \u0434\u0440\u0443\u0433\u0438\u0445 \u0441\u0441\u044B\u043B\u043E\u043A, \u043F\u043E\u043A\u0430 Git \u0438\u0445 \u043D\u0435 \u043E\u0447\u0438\u0441\u0442\u0438\u0442.",
  "branch.deleteAction": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C",
  "branch.deleteAnyway": "\u0412\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0443\u0434\u0430\u043B\u0438\u0442\u044C",
  "branch.mergeTitle": "\u0421\u043B\u0438\u0442\u044C \u0441 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0432\u0435\u0442\u043A\u043E\u0439",
  "branch.mergeText": "\u0421\u043B\u0438\u0442\u044C {branch} \u0432 {current}? Git \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442 \u043F\u0435\u0440\u0435\u043C\u043E\u0442\u043A\u0443, \u0435\u0441\u043B\u0438 \u043C\u043E\u0436\u0435\u0442, \u0438\u043D\u0430\u0447\u0435 \u0441\u043E\u0437\u0434\u0430\u0441\u0442 \u043A\u043E\u043C\u043C\u0438\u0442 \u0441\u043B\u0438\u044F\u043D\u0438\u044F. \u041A\u043E\u043D\u0444\u043B\u0438\u043A\u0442 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442 \u0441\u043B\u0438\u044F\u043D\u0438\u0435 \u0438 \u043E\u0441\u0442\u0430\u0432\u0438\u0442 {current} \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439.",
  "branch.mergeAction": "\u0421\u043B\u0438\u0442\u044C",
  "branch.rebaseTitle": "\u041F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0432\u0435\u0442\u043A\u0443",
  "branch.rebaseText": "\u041F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u043E\u0432\u0430\u0442\u044C {current} \u043D\u0430 {branch}? \u041A\u043E\u043C\u043C\u0438\u0442\u044B {current} \u0431\u0443\u0434\u0443\u0442 \u043F\u0435\u0440\u0435\u043F\u0438\u0441\u0430\u043D\u044B. \u041A\u043E\u043D\u0444\u043B\u0438\u043A\u0442 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442 \u043F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u0438 \u043E\u0441\u0442\u0430\u0432\u0438\u0442 {current} \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439.",
  "branch.rebaseAction": "\u041F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u043E\u0432\u0430\u0442\u044C",
