  "branch.checkoutRemoteText": "\u0421\u043E\u0437\u0434\u0430\u0451\u0442 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0443\u044E \u0432\u0435\u0442\u043A\u0443 \u0438\u0437 {branch} \u0438 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u043D\u0435\u0451. \u041D\u043E\u0432\u0430\u044F \u0432\u0435\u0442\u043A\u0430 \u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u0435\u0442 {remote}.",
