  "branch.deleteRemoteText": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C {branch} \u043D\u0430 \u0435\u0451 \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u043E\u043C \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0438\u0438? \u0412\u0435\u0442\u043A\u0430 \u0438\u0441\u0447\u0435\u0437\u043D\u0435\u0442 \u0443 \u0432\u0441\u0435\u0445, \u043A\u0442\u043E \u0435\u0451 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442.",
