  "branch.deletedRemote": "\u0423\u0434\u0430\u043B\u0451\u043D\u043D\u0430\u044F \u0432\u0435\u0442\u043A\u0430 {branch} \u0443\u0434\u0430\u043B\u0435\u043D\u0430.",
