  "top.readonlySyncBranchTag": "\u0422\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u0435\u043D\u0438\u0435, \u043A\u0440\u043E\u043C\u0435 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0438 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0441 \u0432\u0435\u0442\u043A\u0430\u043C\u0438 \u0438 \u0442\u0435\u0433\u0430\u043C\u0438",
  "top.readonlyHintSyncBranchTag": "\u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u044F\u0435\u0442 \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0438\u0439. \u0421\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u044F \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 fetch, \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u043C\u043E\u0442\u043A\u0443 \u0438\u043B\u0438 push; \u043C\u0435\u043D\u044E \u0432\u0435\u0442\u043E\u043A \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0435\u0442, \u043F\u0435\u0440\u0435\u0438\u043C\u0435\u043D\u043E\u0432\u044B\u0432\u0430\u0435\u0442, \u0443\u0434\u0430\u043B\u044F\u0435\u0442, \u0441\u043B\u0438\u0432\u0430\u0435\u0442, \u043F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u0443\u0435\u0442 \u0438 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0435 \u0432\u0435\u0442\u043A\u0438, \u0430 \u043C\u0435\u043D\u044E \u0442\u0435\u0433\u043E\u0432 \u0443\u0434\u0430\u043B\u044F\u0435\u0442 \u0438\u043B\u0438 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0442\u0435\u0433\u0438. \u0421\u043B\u0438\u044F\u043D\u0438\u0435 \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0431\u0430\u0437\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u0441 \u043A\u043E\u043D\u0444\u043B\u0438\u043A\u0442\u043E\u043C \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
